CREATE TABLE branches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(16) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, address VARCHAR(255) NOT NULL DEFAULT '', phone VARCHAR(30) NOT NULL DEFAULT '', active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE terminals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id BIGINT UNSIGNED NOT NULL, code VARCHAR(16) NOT NULL, UNIQUE(branch_id, code), FOREIGN KEY(branch_id) REFERENCES branches(id));
CREATE TABLE invoice_sequences (branch_id BIGINT UNSIGNED NOT NULL, sequence_date DATE NOT NULL, next_value BIGINT UNSIGNED NOT NULL DEFAULT 1, PRIMARY KEY(branch_id, sequence_date), FOREIGN KEY(branch_id) REFERENCES branches(id));
CREATE TABLE invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, local_invoice_number VARCHAR(50) NOT NULL UNIQUE, cloud_invoice_number VARCHAR(50) NOT NULL UNIQUE, branch_id BIGINT UNSIGNED NOT NULL, terminal_id BIGINT UNSIGNED NOT NULL, cashier_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NULL, subtotal_cents BIGINT NOT NULL, discount_cents BIGINT NOT NULL DEFAULT 0, tax_cents BIGINT NOT NULL DEFAULT 0, total_cents BIGINT NOT NULL, payment_method ENUM('cash','card','credit') NOT NULL, payload_hash CHAR(64) NOT NULL, created_at TIMESTAMP(6) NOT NULL, synced_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), FOREIGN KEY(branch_id) REFERENCES branches(id), FOREIGN KEY(terminal_id) REFERENCES terminals(id));
CREATE TABLE sale_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invoice_id BIGINT UNSIGNED NOT NULL, product_uuid CHAR(36) NOT NULL, product_name VARCHAR(180) NOT NULL, quantity INT NOT NULL, unit_price_cents BIGINT NOT NULL, cost_price_cents BIGINT NOT NULL, line_total_cents BIGINT NOT NULL, FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, module VARCHAR(60) NOT NULL, details JSON NULL, ip_address VARCHAR(45) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(module, created_at));

